    faq_label: "Вопросы и ответы",
    faq_label_short: "FAQ",
    faq_title: "Частые вопросы.",
    faq1_q: "Как работает Landly?",
    faq1_a: "Просматривайте сотни предложений от компаний по всему Израилю и покупайте именно те, которые хотите, по цене, указанной в предложении — без подписки. После покупки покажите QR-код, чтобы воспользоваться им — без карты, без наличных, без лишних хлопот.",
    faq4_q: "Как использовать купоны в заведении?",
    faq4_a: "Все покупки и использование купонов происходят через ваш аккаунт Landly. Купите купон, откройте его в заведении и покажите QR-код сотруднику. Купон автоматически отмечается как использованный.",
    faq5_q: "Можно ли получить возврат за покупку?",
