    faq6_a_post: ", по электронной почте contact@golandly.com. Мы поддерживаем английский, русский, испанский и французский языки и отвечаем в течение 24 часов.",
    home_faq_prompt_pre: "Остались вопросы?",
    home_faq_prompt_link: "Перейти в поддержку",
    footer_tagline: "Живите в Израиле как местный. Скидки, права и сообщество — всё в одном месте.",
    footer_location: "Тель-Авив, Израиль",
    footer_biz_login: "Владелец бизнеса? Войти",
    terms_title: "Условия использования",
    terms_updated_label: "Последнее обновление:",
    terms_updated_date: "октябрь 2026",
    terms_h1: "1. Оплата",
    terms_p1: "Landly работает по модели оплаты за отдельные предложения: вы платите только за те предложения, которые решаете купить, по цене, указанной в этом предложении, без подписки и без периодических списаний какого-либо рода. Все цены указаны в израильских шекелях и включают НДС. Оплата картой производится на защищённой платёжной странице нашего платёжного провайдера Tranzila, соответствующей стандарту PCI-DSS, где данные карты токенизируются; Landly никогда не получает и не хранит полный номер карты или код безопасности (CVV).",
    terms_h2: "2. Отмена и возврат",
    terms_p2a_label: "В течение 14 дней:",
    terms_p2a: "В соответствии с израильским Законом о защите прав потребителей 5741-1981 вы можете отменить покупку в течение 14 дней с даты покупки, если купон ещё не использован. Из суммы возврата может быть удержана плата за отмену — 5% от цены или ₪100, в зависимости от того, что меньше; деньги возвращаются на исходный способ оплаты.",
    terms_p2b_label: "После использования:",
    terms_p2b: "После того как купон использован в заведении, эта покупка считается окончательной и возврату не подлежит.",
    terms_h3: "3. Купоны, предложения и членство",
    terms_p3: "Каждый купон действует в течение срока, указанного в предложении и при оформлении заказа (180 дней с момента покупки, если не указано иное); дата окончания срока видна в вашем кошельке. Купон используется в заведении на условиях, указанных в предложении, привязан к вашему аккаунту Landly и не подлежит передаче.",
    terms_p3b_label: "Только для участников:",
    terms_p3b: "Просматривать привилегии на Landly может любой посетитель без аккаунта. Покупка привилегии, получение и использование кодов ваучеров, а также полные условия и порядок использования от партнёров доступны только зарегистрированным участникам, вошедшим в аккаунт.",
    terms_p3c_label: "Бесплатное членство:",
    terms_p3c: "Создание аккаунта Landly, сохранение членства и цифровая карта участника полностью бесплатны. Нет никаких членских взносов, абонентской платы или автоматических продлений.",
    terms_p3d_label: "Оплата за привилегию:",
    terms_p3d: "Оплата списывается только тогда, когда вы сами решаете купить отдельный купон, по цене, указанной в предложении (см. раздел 1). Landly никогда не списывает средства автоматически или регулярно.",
    terms_h4: "4. Закрытие аккаунта",
    terms_p4a_label: "Как закрыть:",
