    wa_bot_perks_body: "Реальные скидки в отобранных заведениях по всему Израилю. Нажмите ниже, чтобы посмотреть.",
    wa_bot_perks_cta: "Смотреть скидки",
    wa_bot_pass_body_member: "Ваша карта Landly ждёт в аккаунте. Откройте её и покажите в заведении, чтобы получить скидку.",
