    nav_about: "À propos",
    footer_about: "À propos de nous",
    about_title: "Notre histoire",
    about_sub: "Landly existe pour aider les olim, les soldats isolés, les étudiants et les nouveaux arrivants à s'installer et à se sentir chez eux en Israël, avec de vrais avantages, un accompagnement clair et une communauté qui est passée par là.",
    about_founders_title: "Les fondateurs",
