    about_name_omer: "Omer Hirshberg",
    about_role_cofounder: "Cofondateur",
    about_role_cofounder_cto: "Cofondateur et CTO",
    about_bio_amit: "Ancien commandant de char du corps blindé de Tsahal et étudiant en informatique. Co-fondateur et CTO de Landly pour faciliter l'atterrissage financier des Olim et soutenir les entreprises d'immigrants grâce au commerce digital accessible.",
    about_bio_omer: "Ancien officier de la marine israélienne et étudiant en économie. Il a cofondé Landly pour faciliter l'atterrissage financier des olim et soutenir les entreprises tenues par des olim grâce à un commerce numérique accessible.",
    about_linkedin_label: "Profil LinkedIn de {name}",
    about_mission_title: "Pourquoi nous avons créé Landly",
    about_mission_text: "Commencer une vie en Israël, ou y servir loin de sa famille, c'est beaucoup de choses à gérer d'un coup. Landly réunit tout dans un club gratuit : des réductions communautaires chez des commerces locaux sélectionnés, des avantages fiables et un accompagnement personnel, comme un mentor d'Alya qui est passé par là.",
    about_cta_title: "Prêt à découvrir Israël avec Landly ?",
