    terms_link: "Conditions Générales",
    privacy_link: "Politique de confidentialité",
    bottomCta_title: "Prêt à commencer à économiser ?",
    bottomCta_sub: "Rejoignez le club dès aujourd'hui et soyez informé en premier des nouvelles offres et formules.",
    bottomCta_btn: "Inscrivez-vous",
    faq_label: "FAQ",
    faq_label_short: "FAQ",
    faq_title: "Questions fréquentes.",
    faq1_q: "Comment fonctionne Landly ?",
    faq1_a: "Parcourez des centaines d'offres d'entreprises partout en Israël et achetez uniquement celles qui vous intéressent, au prix indiqué sur chaque offre — sans abonnement requis. Après l'achat, présentez votre code QR pour l'utiliser — sans carte, sans espèces, sans tracas.",
    faq4_q: "Comment utiliser les bons chez un commerçant ?",
    faq4_a: "Tous les achats et utilisations de bons se font via votre compte Landly. Achetez un bon, ouvrez-le sur place et présentez le code QR au personnel. Le bon est automatiquement marqué comme utilisé.",
    faq5_q: "Puis-je obtenir un remboursement pour un achat ?",
    faq5_a: "Vous pouvez demander un remboursement intégral à tout moment avant que votre bon pour cette offre n'ait été utilisé chez le commerçant. Une fois qu'un bon a été utilisé, cet achat est définitif et non remboursable.",
    faq_see_full: "Consultez nos",
    faq6_q: "Comment contacter le service client ?",
    faq6_a_pre: "Vous pouvez nous contacter via la",
    faq6_link: "page Service Client",
    faq6_a_post: ", par email à contact@golandly.com. Nous prenons en charge l'anglais, le russe, l'espagnol et le français, et visons à répondre sous 24 heures.",
    home_faq_prompt_pre: "Une question ?",
    home_faq_prompt_link: "Visitez le support",
    footer_tagline: "Vivez Israël comme un local. Vos remises, vos droits et votre communauté au même endroit.",
    footer_location: "Tel Aviv, Israël",
    footer_biz_login: "Vous avez une entreprise ? Connectez-vous ici",
    terms_title: "Conditions Générales",
    terms_updated_label: "Dernière mise à jour :",
    terms_updated_date: "Octobre 2026",
    terms_h1: "1. Paiements",
    terms_p1: "Landly fonctionne au paiement par offre : vous ne payez que les offres que vous choisissez d'acheter, au prix indiqué sur chacune, sans abonnement ni prélèvement récurrent d'aucune sorte. Tous les prix sont en shekels israéliens et incluent la TVA. Les paiements par carte s'effectuent sur la page de paiement sécurisée, conforme à la norme PCI-DSS, hébergée par notre prestataire de paiement Tranzila, qui tokenise vos données de carte ; Landly ne reçoit ni ne conserve jamais votre numéro de carte complet ni votre code de sécurité (CVV).",
    terms_h2: "2. Annulation et Remboursement",
    terms_p2a_label: "Sous 14 jours :",
    terms_p2a: "Conformément à la loi israélienne sur la protection du consommateur, 5741-1981, vous pouvez annuler un achat dans les 14 jours suivant sa date, tant que le bon n'a pas été utilisé. Des frais d'annulation de 5 % du prix ou de 100 ₪, le montant le plus bas, peuvent être déduits du remboursement, effectué sur le moyen de paiement d'origine.",
    terms_p2b_label: "Après utilisation :",
    terms_p2b: "Une fois le bon utilisé dans l'établissement, l'achat est définitif et non remboursable.",
    terms_h3: "3. Bons, Offres et Adhésion",
    terms_p3: "Chaque bon est valable pendant la durée indiquée sur son offre et lors du paiement (180 jours à compter de l'achat, sauf mention contraire) ; sa date d'expiration figure dans votre portefeuille. Les bons s'utilisent dans l'établissement selon les conditions indiquées sur l'offre, sont liés à votre compte Landly et ne sont pas transférables.",
    terms_p3b_label: "Réservé aux membres :",
    terms_p3b: "Tout le monde peut parcourir les avantages présentés sur Landly sans compte. L'achat d'un avantage, la réception et l'utilisation des codes de bon, ainsi que les conditions et modalités complètes du partenaire sont réservés aux membres inscrits et connectés.",
    terms_p3c_label: "Adhésion gratuite :",
    terms_p3c: "La création d'un compte Landly, le maintien de votre adhésion et la détention de votre carte de membre numérique sont entièrement gratuits. Il n'y a aucuns frais d'adhésion, aucun abonnement ni aucun renouvellement automatique.",
    terms_p3d_label: "Paiement par avantage :",
    terms_p3d: "Vous n'êtes débité que lorsque vous choisissez d'acheter un bon à l'unité, au prix indiqué dans son offre (voir section 1). Landly ne vous débite jamais automatiquement ni de manière récurrente.",
    terms_h4: "4. Fermeture du Compte",
    terms_p4a_label: "Comment fermer :",
    terms_p4a: "Vous pouvez à tout moment nous demander de fermer votre compte Landly et de supprimer vos données personnelles, dans Paramètres → Supprimer le compte sur le site ou dans l'application, ou en écrivant à contact@golandly.com depuis l'adresse associée à votre compte.",
    terms_p4b_label: "Sous 30 jours :",
    terms_p4b: "Nous supprimons votre compte et vos données personnelles, et vous le confirmons par e-mail, dans les 30 jours suivant votre demande. Les données de commande et de transaction que la loi nous oblige à conserver sont gardées, sans lien avec un compte actif, comme décrit dans notre Politique de confidentialité.",
    terms_p4c_label: "Bons non utilisés :",
    terms_p4c: "La fermeture du compte annule les bons que vous n'avez pas utilisés, sans possibilité de les restaurer. Si un achat est encore dans son délai d'annulation de 14 jours, annulez-le comme indiqué à la section 2 avant de demander la fermeture du compte ; nous le rembourserons sur votre moyen de paiement d'origine.",
    terms_p4_link: "Accéder à la suppression du compte",
    terms_h6: "6. Droit Applicable",
    terms_p6: "Les présentes conditions sont régies par les lois de l'État d'Israël. Les tribunaux compétents de Tel Aviv-Yafo ont compétence exclusive pour tout litige découlant de celles-ci ou de votre utilisation de Landly.",
    terms_h7: "7. Vendeur et Contact",
    terms_p7: "Landly est exploité depuis Tel Aviv-Yafo, en Israël. Pour toute question sur ces conditions, une commande ou une annulation, écrivez-nous à contact@golandly.com.",
