    wa_bot_team_confirm: "Merci ! Nous avons prévenu l’équipe, quelqu’un vous répondra ici très bientôt. 🙏",
    wa_bot_team_already: "L’équipe a déjà reçu votre demande et vous répondra ici très bientôt.",
