    terms_title: "תנאי שימוש",
    terms_updated_label: "עודכן לאחרונה:",
    terms_updated_date: "אוקטובר 2026",
    terms_h1: "1. תשלומים",
    terms_p1: "Landly פועלת בתשלום לפי הטבה: משלמים רק על ההטבות שבוחרים לקנות, במחיר המופיע בכל הטבה, ללא מנוי וללא חיובים חוזרים מכל סוג. כל המחירים בשקלים וכוללים מע״מ. תשלום בכרטיס מתבצע בעמוד התשלום המאובטח של ספק התשלומים שלנו, טרנזילה (Tranzila), העומד בתקן PCI-DSS והופך את פרטי הכרטיס לאסימון (טוקן); Landly לעולם אינה מקבלת או שומרת את מספר הכרטיס המלא או את קוד האבטחה (CVV).",
    terms_h2: "2. ביטול עסקה והחזרים",
    terms_p2a_label: "בתוך 14 ימים:",
    terms_p2a: "בהתאם לחוק הגנת הצרכן, התשמ״א-1981, ניתן לבטל רכישה בתוך 14 ימים ממועד הרכישה, כל עוד השובר לא מומש. מההחזר עשויים להיות מנוכים דמי ביטול בשיעור 5% מהמחיר או ‎₪100, הנמוך מביניהם, וההחזר יבוצע לאמצעי התשלום המקורי.",
    terms_p2b_label: "לאחר מימוש:",
    terms_p2b: "לאחר שהשובר מומש בבית העסק, הרכישה סופית ואינה ניתנת להחזר.",
    terms_h3: "3. קופונים, הטבות וחברות",
    terms_p3: "כל שובר בתוקף לתקופה המופיעה בהטבה ובעמוד התשלום (180 ימים ממועד הרכישה, אלא אם צוין אחרת), ותאריך התפוגה שלו מוצג בארנק. השובר ממומש בבית העסק לפי תנאי המימוש המופיעים בהטבה, משויך לחשבון Landly שלך ואינו ניתן להעברה.",
    terms_p3b_label: "לחברי המועדון בלבד:",
    terms_p3b: "כל אחד יכול לעיין בהטבות המוצגות ב-Landly גם בלי חשבון. רכישת הטבה, קבלה ומימוש של קודי שוברים, וצפייה בפרטי המימוש ובתנאים המלאים של העסק השותף זמינים רק לחברים רשומים המחוברים לחשבון.",
    terms_p3c_label: "חברות חינם:",
    terms_p3c: "פתיחת חשבון ב-Landly, שמירה על החברות והחזקת כרטיס החבר הדיגיטלי הם ללא עלות כלל. אין דמי חברות, אין דמי מנוי ואין חידושים אוטומטיים מכל סוג שהוא.",
    terms_p3d_label: "חיוב רק ברכישה:",
    terms_p3d: "חיוב מתבצע רק כאשר אתם בוחרים לרכוש שובר מסוים, במחיר המוצג בהטבה (ראו סעיף 1). Landly לעולם לא מחייבת אתכם באופן אוטומטי או מחזורי.",
    terms_h4: "4. סגירת החשבון",
    terms_p4a_label: "איך סוגרים:",
    terms_p4a: "אפשר לבקש בכל עת לסגור את חשבון Landly ולמחוק את המידע האישי שלך, דרך הגדרות ← מחיקת חשבון באתר או באפליקציה, או במייל אל contact@golandly.com מהכתובת הרשומה בחשבון.",
    terms_p4b_label: "בתוך 30 ימים:",
    terms_p4b: "נמחק את החשבון ואת המידע האישי שלך ונאשר זאת במייל, בתוך 30 ימים ממועד הבקשה. רשומות הזמנה ועסקה שאנו חייבים לשמור על פי דין נשמרות, ללא קישור לחשבון פעיל, כמפורט במדיניות הפרטיות.",
    terms_p4c_label: "שוברים שלא מומשו:",
